// ═══════════════════════════════════════════════════════════════
// ZELLU CHAT - Formatação de Resposta da IA
// Versão: 3.1 (com suporte a Group Messages)
// Documentação: docs/AI_SERVICE_WEBHOOK_FORMAT.md
// ═══════════════════════════════════════════════════════════════

const response = $input.first().json.response;
const chatId = $('Webhook - Receber do Zellu').first().json.chat_id;

// Detectar se deve finalizar análise
const shouldFinish = response.toLowerCase().includes('criar chamado') || 
                     response.toLowerCase().includes('abrir ticket');

// ─────────────────────────────────────────────────────────────
// 📌 CENÁRIO 1: MENSAGEM SIMPLES (Recomendado para começar)
// ─────────────────────────────────────────────────────────────
// Use este formato para respostas únicas e diretas

const simpleResponse = {
  chat_id: chatId,
  message: response,
  is_finished: shouldFinish,
  message_type: 'text',
  files: [],
  audio: null,
  // analysis_data: shouldFinish ? generateAnalysisData() : null
};

// ─────────────────────────────────────────────────────────────
// 📌 CENÁRIO 2: GROUP MESSAGES (Mensagens Sequenciais)
// ─────────────────────────────────────────────────────────────
// Use este formato para simular "Digitando..." como WhatsApp
// Descomente o bloco abaixo para testar:

