// ─────────────────────────────────────────────────────────────
// 📌 HELPER: Gerar analysis_data (quando is_finished=true)
// ─────────────────────────────────────────────────────────────

function generateAnalysisData() {
  return {
    problem: "Cobrança indevida após cancelamento de serviço",
    rights: [
      "Direito à devolução em dobro (CDC, Art. 42)",
      "Direito ao cancelamento sem ônus (CDC, Art. 49)",
      "Direito à indenização por danos morais (CDC, Art. 6º, VI)"
    ],
    estimatedValue: 3598.50,
    recommendations: [
      {
        type: "amigavel",
        score: 9.2,
        reason: "Alta chance de resolução rápida"
      },
      {
        type: "extrajudicial",
        score: 7.5,
        reason: "Recomendado se amigável falhar"
      },
      {
        type: "judicial",
        score: 5.8,
        reason: "Última opção, prazo mais longo"
      }
    ],
    userInfo: {
      name: "João Silva",
      cpf: "123.456.789-00",
      email: "joao@email.com",
      phone: "(11) 99999-1111",
      address: "Rua Exemplo, 123 - São Paulo/SP"
    },
    opposingParty: {
      type: "pj",
      name: "Empresa XYZ Ltda",
      document: "12.345.678/0001-90",
      email: "contato@xyz.com",
      phone: "(11) 3000-1000",
      address: "Av. Principal, 1000 - São Paulo/SP"
    },
    caseDetails: {
      title: "Cobrança Indevida",
      description: "Cliente cancelou mas continua sendo cobrado",
